func onboardingHouseholdTemplate() string {
	return strings.NewReplacer(
		`Your Owner account is ready. Add profiles for adults and choose age ratings for children.`, `Your Owner account is ready. Add the people who watch; you can finish this later in Settings.`,
		`<p><a class="mode" href="/onboarding/migrate">Continue to viewing history</a> <a class="mode" href="/onboarding/finish">Finish later</a></p>`, `<p class="onboarding-actions"><a class="mode" href="/onboarding/migrate">Continue to optional viewing history</a> <a class="mode" href="/onboarding/finish">Finish and open Library</a></p>`,
	).Replace(strings.Replace(onboardingHouseholdHTML, `/static/app.css?v=electric-1`, `/static/app.css?v=electric-1`, 1))
}

func jellyfinTrustedHTTPSPage(page string) string {
	start := `<section id="jellyfin" data-settings-group="access">`
	end := `<section id="trusted-https" data-settings-group="access">`
	before, rest, found := strings.Cut(page, start)
	if !found {
		return page
	}
	_, after, found := strings.Cut(rest, end)
	if !found {
		return page
	}
	after = strings.NewReplacer(
		`<h2>Trusted HTTPS with DuckDNS (Recommended)</h2>`, `<h2>Trusted HTTPS with DuckDNS (Required for Jellyfin apps)</h2>`,
		`<strong>Recommended for phones, TVs, and apps. Optional.</strong>`, `<strong>Required for Jellyfin apps. Recommended for phones and TVs.</strong>`,
	).Replace(after)
	return providerNeutralTrustedHTTPSPage(before + jellyfinSettingsHTML + end + after)
}

func showOnboardingHousehold(profiles *profileStore) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		writer.Header().Set("Content-Type", "text/html; charset=utf-8")
		writer.Header().Set("Cache-Control", "no-store")
		if err := onboardingHouseholdView.Execute(writer, request, struct {
			Profiles []viewerProfile
			Step     string
		}{profiles.list(), "household"}); err != nil {
			localizedError(writer, request, "household onboarding failed", http.StatusInternalServerError)
		}
	}
}

func showOnboardingStart(writer http.ResponseWriter, request *http.Request) {
	http.Redirect(writer, request, "/onboarding/connection", http.StatusSeeOther)
}

func finishOnboarding(settings *settingsStore) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		if err := settings.setOnboardingPending(false); err != nil {
			localizedError(writer, request, "could not finish onboarding", http.StatusInternalServerError)
			return
		}
		http.Redirect(writer, request, "/", http.StatusSeeOther)
	}
}

func restartOnboarding(settings *settingsStore) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		if err := settings.setOnboardingPending(true); err != nil {
			localizedError(writer, request, "could not restart onboarding", http.StatusInternalServerError)
			return
		}
		http.Redirect(writer, request, "/onboarding", http.StatusSeeOther)
	}
}

func showSettings(settings *settingsStore, updates *updateChecker, profiles *profileStore, internet *remoteaccess.Manager, trusted *trustedhttps.Manager, audit *auditStore, index *libraryIndex, hls *hlsManager, subtitles *subtitleProvider, metadata *metadataStore, markers *markerAnalyzer, maintenance *maintenanceManager, imports *viewingImportManager, notifications, authURL string) http.HandlerFunc { //nolint:funlen,gocognit // The settings view assembles one read-only projection.
	return func(writer http.ResponseWriter, request *http.Request) {
		writer.Header().Set("Content-Type", "text/html; charset=utf-8")
		transcoding := settings.transcoding()
		items, scanned, scanErr := index.Status()
		cache, cacheErr := hls.cacheOps.Stats()
		internetStatus := remoteaccess.Status{State: "disabled", Mode: "off"}
		if internet != nil {
			internetStatus = internet.Status()
		}
		trustedStatus := trustedhttps.Status{State: "disabled"}
		if trusted != nil {
			trustedStatus = trusted.Status()
		}
		trustedView := settings.trustedHTTPS()
		scanFrequency, subtitleLanguage := settings.scanFrequency(), settings.subtitleLanguage()
		autoplay, autoSkip := settings.autoplay(), settings.autoSkip()
		transcoderCheck := settings.transcoderState().CheckCoordinator(settings.ffmpeg, settings.hardware).Current()
		markerState, markerItems, markerError := markers.Status()
		watching, _ := index.Monitoring()
		navigation := settings.navigationPreferences(preferredLanguage(request))
		updateView := updates.View()
		configured := settings.configuration()
		managed := make([]string, 0)
		for _, field := range configured.Fields() {
			if configured.Managed(field.Key) {
				managed = append(managed, field.Key+" ("+string(field.Source)+")")
			}
		}
		value := settings.snapshot()
		playback := normalizePlayback(value.PlaybackMode)
		data := struct {
			Name, MediaRoot                                              string
			Libraries                                                    []string
			Profiles                                                     []viewerProfile
			Playback, Transcoder, Codec                                  string
			Accelerator, AutomaticHardware                               string
			Hardware                                                     []hardwareBackend
			Codecs                                                       []videoCodecCapability
			ToneMap                                                      bool
			Autoplay                                                     bool
			SkipIntro, SkipRecap, SkipCommercial, SkipOutro, SkipCredits bool
			Items                                                        int
			Scanned                                                      string
			ScanError                                                    error
			Subtitles                                                    string
			ScanFrequency                                                string
			Sessions                                                     int
			Devices                                                      []deviceSession
			APIKeys                                                      []apiKeyView
			Cache                                                        string
			SubtitleProvider, SubtitleLanguage, MetadataProvider         string
			DLNA                                                         string
			DLNAAvailable                                                bool
			DLNAEnabled                                                  bool
			OIDCConfigured, SAMLConfigured                               bool
			Notifications                                                string
			MarkerState, MarkerError                                     string
			MarkerItems                                                  int
			Watching                                                     bool
			Managed                                                      []string
			MFAControl, ServerControl, PlaybackControl                   settingControl
			SubtitleControl, TranscoderControl, JellyfinControl          settingControl
			DLNAControl, LibrariesControl, ScansControl                  settingControl
			Maintenance                                                  sharedmaintenance.Status
			ViewingSyncs                                                 []viewingSyncView
			RequireMFA                                                   bool
			TranscoderTest                                               transcodepolicy.CheckResult
			JellyfinCompatibility                                        bool
			Internet                                                     remoteaccess.Status
			Trusted                                                      trustedHTTPSView
			TrustedStatus                                                trustedhttps.Status
			TrustedControl                                               settingControl
			SecurityAlert                                                string
			Navigation                                                   []navigationPreference
			SessionInactiveHours, SessionAbsoluteHours                   float64
			OnboardingPending                                            bool
			Updates                                                      updateStatus
			UpdateText                                                   string
			UpdateManagerText                                            string
			HomeAssistant                                                bool
			HomeAssistantControl                                         settingControl
			MetadataControl, OIDCControl, SAMLControl, SCIMControl       settingControl
			WebhookControl                                               settingControl
			DLNAURLControl, BackupControl                                settingControl
			SCIMConfigured, SCIMExpired                                  bool
			JellyfinURL                                                  string
		}{value.Name, settings.mediaRoot, value.Libraries, profiles.list(), playback, transcoding.Name, normalizeCodecSetting(value.Codec), normalizeAccelerator(value.Accelerator), settings.hardware.Backend(settings.hardware.Resolve("auto")).FriendlyName(), settings.hardware.Backends, settings.hardware.CurrentCodecs(), value.ToneMap, autoplay, slices.Contains(autoSkip, "intro"), slices.Contains(autoSkip, "recap"), slices.Contains(autoSkip, "commercial"), slices.Contains(autoSkip, "outro"), slices.Contains(autoSkip, "credits"), items, scanned.Local().Format("Jan 2, 2006 3:04 PM MST"), scanErr, value.Subtitles, scanFrequency, profiles.activeSessions(), profiles.devices(), profiles.apiKeyViews(), byteSize(cache), subtitles.label(), subtitleLanguage, metadata.label(), dlnaLabel(settings), settings.dlnaURL != "", value.DLNAToken != "", configured.String("integrations.oidc.issuer") != "", samlConfigured(configured), notifications, markerState, markerError, markerItems, watching, managed, configurationControl(configured, "security.require_mfa"), configurationControl(configured, "server.name"), configurationControl(configured, "playback.mode", "playback.autoplay", "playback.subtitles", "playback.auto_skip"), configurationControl(configured, "subtitles.language"), configurationControl(configured, "transcoding.quality", "transcoding.codec", "transcoding.accelerator", "transcoding.tone_map"), configurationControl(configured, "integrations.jellyfin.enabled"), configurationControl(configured, "dlna.enabled"), configurationControl(configured, "libraries"), configurationControl(configured, "scanning.frequency"), maintenance.Status(), imports.list(), value.RequireMFA, transcoderCheck, value.JellyfinCompatibility, internetStatus, trustedView, trustedStatus, configurationControl(configured, "tls.duckdns"), audit.TripwireWarning(), navigation, 0, 0, value.OnboardingPending, updateView, updateStatusText(updateView), updateManagerStatusText(updateView.Manager), value.HomeAssistant, configurationControl(configured, "integrations.home_assistant.enabled"), configurationControl(configured, "integrations.tmdb.url", "integrations.tmdb.image_url", "integrations.tmdb.token"), configurationControl(configured, "integrations.oidc.issuer", "integrations.oidc.client_id", "integrations.oidc.client_secret", "integrations.oidc.redirect_url"), configurationControl(configured, samlConfigurationKeys...), configurationControl(configured, scimConfigurationKeys...), configurationControl(configured, "integrations.webhook.url", "integrations.webhook.token"), configurationControl(configured, "dlna.url"), configurationControl(configured, "backup.directory", "backup.key", "backup.interval", "backup.retention"), configured.String("integrations.scim.token") != "", scimExpired(configured.String("integrations.scim.token_expires_at"), time.Now()), authURL}
		data.SessionInactiveHours, data.SessionAbsoluteHours = sessionTimeoutHours(value)
		data.JellyfinCompatibility = settings.jellyfinCompatibility()
		if data.JellyfinCompatibility {
			data.JellyfinControl.ConnectionURL = trustedConnectionURL(authURL, data.Trusted.Hostname)
		}
		if cacheErr != nil {
			data.Cache = "Unavailable"
		}
		if err := settingsView.Execute(writer, request, data); err != nil {
			localizedError(writer, request, err.Error(), http.StatusInternalServerError)
		}
	}
}
